const names=Object.freeze({COTTON:'Cotton',IRON_ORE:'Iron ore',SUGAR:'Sugar',WOOD:'Wood',FOOD:'Food',RUM:'Rum',TEXTILES:'Textiles',IRON_BARS:'Iron bars',CANNONS:'Cannons',CANNONBALLS:'Cannonballs',SPICES:'Spices'});
const name=id=>names[id]??String(id??'Unknown goods').replaceAll('_',' ');
const quantity=value=>Number.isInteger(value)?String(value):Number(value??0).toFixed(2).replace(/0+$/,'').replace(/\.$/,'');
const inputText=rows=>(rows??[]).map(row=>`${name(row.commodity_id??row.commodityId)} ${quantity(row.quantity_per_tick??row.quantity)}`).join(', ')||'None';
const outputText=rows=>(rows??[]).map(row=>`${name(row.commodity_id??row.commodityId)} ${quantity(row.quantity_per_tick??row.quantity)}`).join(', ')||'None';
const commodityIcons=Object.freeze({COTTON:'./gfx/industries/cotton.svg',IRON_ORE:'./gfx/industries/iron.svg',IRON_BARS:'./gfx/industries/iron.svg',SUGAR:'./gfx/industries/sugar.svg',RUM:'./gfx/industries/rum_distillery.svg',TEXTILES:'./gfx/industries/textile_mill.svg',CANNONS:'./gfx/industries/cannon_foundry.svg',CANNONBALLS:'./gfx/industries/cannonball_foundry.svg'});
const iconFor=id=>commodityIcons[id]??null;
const clockLabel=seconds=>{const value=Math.max(0,Number(seconds)||0),minutes=Math.floor(value/60),remaining=Math.floor(value%60);return `${minutes}:${String(remaining).padStart(2,'0')}`;};
const priceText=(amount,price)=>`${quantity(amount)} @ ${Number(price??0).toFixed(2)} gold`;
const tradeAction=action=>action==='delivery'?'Unloaded cargo':action==='pickup'?'Loaded cargo':action==='discovery'?'Discovery':action==='allocation'?'Local allocation':action?String(action).replaceAll('_',' '):'Market activity';
const buyerName=(id,port)=>{if(!id)return '—';const value=String(id);if(value.startsWith('PORT:')){const owner=value.slice(5);if(owner===port.id)return `${port.name??owner} treasury`;return `${owner} treasury`;}if(value.startsWith('MERCHANT:'))return `Merchant ${value.slice(9)}`;return value.replace(/^INDUSTRY:/,'Industry ');};
const tradeRows=(port,info,histories)=>{const rows=[],seen=new Set();for(const history of histories??[]){const portHistory=history.ports?.find(item=>item.id===port.id)??history.ports?.[0];for(const event of portHistory?.events??[]){const key=`${history.commodityId}:${event.id??event.endTime??event.startTime}:${event.shipId??event.shipName??''}`;if(seen.has(key))continue;seen.add(key);rows.push({time:clockLabel(event.endTime??event.startTime??0),sortTime:Number(event.endTime??event.startTime??0),vessel:event.shipName??event.shipId??'Unidentified trader',action:tradeAction(event.action),goods:name(history.commodityId),quantity:event.quantity===undefined?'—':quantity(event.quantity),buyer:buyerName(event.buyerAccountId,port),route:event.action==='delivery'?`From ${event.originPortId??'an unknown port'}`:event.action==='pickup'?`To ${event.destinationPortId??'an unknown port'}`:event.action==='discovery'?'Market discovery':'Local stores',state:event.action==='discovery'?'Reported':'Complete'});}}
 if(!rows.length)for(const event of info?.trades??[])rows.push({time:event.tick===undefined?'—':`Tick ${event.tick}`,sortTime:Number(event.tick??0),vessel:event.shipName??event.shipId??'Market participant',action:tradeAction(event.action),goods:name(event.commodityId),quantity:event.quantity===undefined?'—':quantity(event.quantity),buyer:buyerName(event.buyerAccountId,port),route:event.action==='delivery'?`From ${event.originPortId??'an unknown port'}`:event.action==='pickup'?`To ${event.destinationPortId??'an unknown port'}`:'Market activity',state:'Complete'});
 rows.sort((a,b)=>b.sortTime-a.sortTime);return rows.slice(0,80).map(({sortTime,...row})=>row);};

/* The demo adapter is also the fallback when the simulation has not started. */
export function createDemoLedgerData(port={}){
 const portName=port.name??'Port Aurelia',faction=port.factionName??'British';
 return {
  meta:{title:portName,subtitle:faction,eyebrow:'PORT LEDGER'},
  pages:{
   dock:{left:{eyebrow:'DOCK',title:'The harbour at a glance',summary:'The dock page is the working home of the port: population, treasury, berths and the latest harbour activity.',context:'A dockmaster keeps this page current as ships arrive, load, unload and depart.',facts:[{label:'Colony',value:port.colonyName??'Aurelia'},{label:'Governor',value:'Eleanor Hart'},{label:'Harbour',value:'Open for trade'},{label:'Last report',value:'Tick 840'}]},right:{eyebrow:'HARBOUR REGISTER',summaryTitle:'Dock and town summary',metrics:[{label:'Population',value:4820,format:'integer',detail:'souls registered'},{label:'Treasury',value:12840.5,format:'money',detail:'population wealth'},{label:'Active ships',value:7,format:'integer',detail:'in harbour or at sea'},{label:'Open notices',value:4,format:'integer',detail:'awaiting attention'}],rows:[{dock:'North quay',status:'Open',ships:'3 / 6'},{dock:'Merchant quay',status:'Loading',ships:'2 / 4'},{dock:'Outer anchorage',status:'Waiting',ships:'2 / 8'}],context:'The dock page records the port itself. Market depth, voyages and factory books have their own folios.'}},
   tavern:{left:{eyebrow:'TAVERN',title:'News from the common room',summary:'Reports brought by sailors are posted here until they grow too old to trust.',bulletins:['Contract: textiles wanted at Port Royal before the next convoy.','Shortage: sugar stocks are thin across the western islands.','Piracy: the Sea Lark was robbed and limped into Saint Elmo.'],context:'Tavern reports are observations, not guarantees. Their age and source matter.'},right:{eyebrow:'TAVERN BOARD',ledgerTitle:'News and notices',stories:[{kind:'Contract',report:'Textiles wanted at Port Royal',age:'Fresh'},{kind:'Shortage',report:'Sugar scarce in the western islands',age:'2 watches old'},{kind:'Piracy',report:'Sea Lark robbed by Captain Vane',age:'4 watches old'}],context:'Stories expire when they are too stale to guide a voyage. New reports arrive with visiting ships.'}},
   industries:{left:{eyebrow:'INDUSTRIES',title:'Works within the catchment',summary:'All primary works and manufacturing houses attached to this port appear in one register.',metrics:[{label:'Active industries',value:3,format:'integer',detail:'connected to this port'},{label:'Primary works',value:2,format:'integer',detail:'raw materials'},{label:'Factories',value:1,format:'integer',detail:'manufactured goods'},{label:'Output this watch',value:18,format:'integer',detail:'goods units'}],productionNotes:['Sugar plantation: supplying the local market.','Cotton plantation: supplying the textile trade.','Rum distillery: waiting for sugar and wood.']},right:{eyebrow:'INDUSTRY REGISTER',registerTitle:'Port industries',rows:[{industry:'Sugar plantation',instance:'sugar · Aurelia-1',inputs:'None',outputs:'Sugar 2',status:'Producing'},{industry:'Cotton plantation',instance:'cotton · Aurelia-1',inputs:'None',outputs:'Cotton 2',status:'Producing'},{industry:'Rum distillery',instance:'rum · Aurelia-1',inputs:'Sugar 2, Wood .5',outputs:'Rum 1.5',status:'Waiting for inputs'}],context:'Each row represents one identifiable owner. Additional factories will appear here without merging their accounts.'}},
   markets:{left:{eyebrow:'MARKETS',title:'Offers and wants',summary:'Only active market depth belongs on this page. Empty goods are omitted by the data source.',rows:[{commodityId:'RUM',goods:'Rum',icon:iconFor('RUM'),wanted:'200 @ 12.00 gold',offers:'80 @ 14.00 gold'},{commodityId:'TEXTILES',goods:'Textiles',icon:iconFor('TEXTILES'),wanted:'60 @ 9.50 gold',offers:'40 @ 11.00 gold'},{commodityId:'WOOD',goods:'Wood',wanted:'—',offers:'120 @ 3.25 gold'}],knowledgeTitle:'World knowledge',knowledge:[{port:'Port Royal',goods:'Rum',icon:iconFor('RUM'),wanted:'40 @ 13.00 gold',offers:'20 @ 15.00 gold',age:'Fresh'},{port:'Saint Elmo',goods:'Textiles',icon:iconFor('TEXTILES'),wanted:'25 @ 10.00 gold',offers:'—',age:'3 ticks old'}]},right:{eyebrow:'MARKET REMARKS',title:'Rum price history',summary:'Offers and wants are funded, finite and owner-attributed.',priceHistory:{title:'Rum offer price',unit:'gold',points:[{label:'1',value:10},{label:'2',value:12},{label:'3',value:11},{label:'4',value:14},{label:'5',value:13}],ranges:[{seconds:0,label:'All'},{seconds:600,label:'10 min'},{seconds:300,label:'5 min'}],selectedRange:0},source:{observedAt:'Tick 840',confidence:.86},context:'An offer or want is information until a funded settlement accepts it.'}},
   trades:{left:{eyebrow:'TRADES',title:'Dockside trade register',summary:'Every recent dock call is recorded by vessel, action, goods, quantity and buyer.',rows:[{time:'08:40',vessel:'Sea Lark',action:'Unloaded cargo',goods:'Textiles',quantity:'12',buyer:'Port Royal treasury'},{time:'09:10',vessel:'Mercy Bell',action:'Discovery',goods:'—',quantity:'—',buyer:'—'},{time:'10:00',vessel:'North Star',action:'Loaded cargo',goods:'Rum',quantity:'8',buyer:'Mercy Bell'}]},right:{eyebrow:'TRADE NOTES',title:'Recent dock activity',timeline:[{label:'08:40',detail:'Sea Lark unloaded 12 Textiles for Port Royal treasury',state:'Complete'},{label:'09:10',detail:'Mercy Bell brought a market discovery',state:'Reported'},{label:'10:00',detail:'North Star loaded 8 Rum for Mercy Bell',state:'Complete'}],context:'A dock call may report a discovery as well as loading or unloading. Actual settlement and physical handling remain separate records.'}},
   accounts:{left:{eyebrow:'ACCOUNTS',title:'Accounts and purses',metrics:[{label:'Port treasury',value:12840.5,format:'money',detail:'population wealth'},{label:'Industry funds',value:2190,format:'money',detail:'operating accounts'},{label:'Committed',value:640,format:'money',detail:'not spendable'},{label:'Running costs',value:18.75,format:'money',detail:'ship purses aboard'}],facts:[{label:'Money precision',value:'Microgold'},{label:'Worker share',value:'Configured'},{label:'Upkeep',value:'Disabled'}],summary:'Balances, commitments and spendable funds remain separate in the account register.'},right:{eyebrow:'ACCOUNT REGISTER',title:'Open accounts',rows:[{account:'Port treasury',balance:12840.5,status:'Spendable'},{account:'Distillery · Aurelia-1',balance:960,status:'Operating'},{account:'Merchant · Sea Lark',balance:330,status:'At sea'}],context:'Money is formatted for display only. Stored balances remain integer microgold.'}}
  }
 };
}

export function createPortLedgerData(port={},info=null,{histories=[],selectedCommodity=null,rangeSeconds=0}={}){
 const data=createDemoLedgerData(port);if(!info)return data;
 const meta=info.meta??{},industries=info.industries??[],primary=info.primary??[],treasury=Number(info.treasury?.balance??0),orders=info.orders??[],offers=info.offers??[];
 data.meta={...data.meta,title:info.name??port.name??data.meta.title,subtitle:info.faction??port.factionName??data.meta.subtitle};
 data.pages.dock.left.facts=[{label:'Colony',value:meta.colonyName??port.colonyName??'Unknown'},{label:'Settlement',value:meta.settlementType??'Port'},{label:'Prosperity',value:Number(meta.prosperity??0).toFixed(2)},{label:'Last report',value:`Tick ${info.tick??'—'}`}];
 data.pages.dock.right.metrics[0].value=meta.population??0;data.pages.dock.right.metrics[1].value=treasury;data.pages.dock.right.metrics[2].value=info.harbor?.activeShips??data.pages.dock.right.metrics[2].value;data.pages.dock.right.metrics[3].value=orders.length+offers.length;
 data.pages.industries.left.metrics=[{label:'Active industries',value:primary.length+industries.length,format:'integer',detail:'connected to this port'},{label:'Primary works',value:primary.length,format:'integer',detail:'raw materials'},{label:'Factories',value:industries.length,format:'integer',detail:'manufactured goods'},{label:'Open projects',value:(info.construction??[]).length,format:'integer',detail:'under construction'}];
 data.pages.industries.left.productionNotes=[...primary.map(item=>`${item.name}: ${outputText(item.outputs)}.`),...industries.map(item=>`${item.name} ${item.ready?'has inputs ready':'is waiting for inputs'}.`)];
 data.pages.industries.right.rows=[...primary.map(item=>({industry:item.name,instance:item.id??'Primary work',inputs:'None',outputs:outputText(item.outputs),status:'Producing'})),...industries.map(item=>({industry:item.name,instance:item.instanceId??item.id,inputs:inputText(item.inputs),outputs:outputText(item.outputs),status:item.productionMode==='ELAPSED_SIMULATION_TIME'?(item.ready?'Ready':'Waiting for inputs'):'Not active'}))];
 const trades=tradeRows(port,info,histories);data.pages.trades.left.rows=trades;data.pages.trades.left.summary=trades.length?'Recent dock calls, cargo movements and discoveries at this port.':'No dockside trade activity has been recorded for this port yet.';data.pages.trades.right.timeline=trades.slice(0,12).map(row=>({label:row.time,detail:`${row.vessel}: ${row.action} · ${row.quantity} ${row.goods} · buyer ${row.buyer}`,state:row.state}));data.pages.trades.right.context=trades.length?'Trade history is bounded and records the actual dockside event, including the buyer where one exists.':'When ships begin calling, their loading, unloading and discoveries will appear here.';
 data.pages.accounts.left.metrics[0].value=treasury;data.pages.accounts.left.metrics[1].value=industries.reduce((sum,item)=>sum+Number(item.account?.balance??0),0);data.pages.accounts.left.metrics[2].value=industries.reduce((sum,item)=>sum+Number(item.account?.committed??0),0);data.pages.accounts.left.facts=[{label:'Money precision',value:'Microgold'},{label:'Worker share',value:`${Math.round(Number(info.workerShare??0)*100)}%`},{label:'Open orders',value:String(orders.length)},{label:'Open offers',value:String(offers.length)}];
 const market=new Map();const rowFor=commodityId=>{const row=market.get(commodityId)??{commodityId,goods:name(commodityId),icon:iconFor(commodityId),wantedLevels:[],offerLevels:[]};market.set(commodityId,row);return row;};for(const order of orders.filter(order=>Number(order.remainingQuantity)>0)){const row=rowFor(order.commodityId);row.wantedLevels.push(priceText(order.remainingQuantity,order.offeredPrice));}for(const offer of offers.filter(offer=>Number(offer.remainingQuantity)>0)){const row=rowFor(offer.commodityId);row.offerLevels.push(priceText(offer.remainingQuantity,offer.askingPrice));}for(const row of market.values()){row.wanted=row.wantedLevels.join(' · ')||'—';row.offers=row.offerLevels.join(' · ')||'—';delete row.wantedLevels;delete row.offerLevels;}
 data.pages.markets.left.rows=[...market.values()];data.pages.markets.left.summary=market.size?'Active funded demand and owner-attributed supply at this port.':'No active funded market orders or offers at this port.';
 const knowledge=[];for(const entry of info.worldKnowledge??[]){for(const [commodityId,price] of Object.entries(entry.prices??{})){const hasOffer=Number(price.askQuantity)>0&&Number.isFinite(Number(price.ask));const hasWant=Number(price.bidQuantity)>0&&Number.isFinite(Number(price.bid));if(!hasOffer&&!hasWant)continue;knowledge.push({port:entry.portName??entry.portId,goods:name(commodityId),icon:iconFor(commodityId),wanted:hasWant?priceText(price.bidQuantity,price.bid):'—',offers:hasOffer?priceText(price.askQuantity,price.ask):'—',age:Number(entry.age)>0?`${quantity(entry.age)} ticks old`:'Fresh'});}}
 knowledge.sort((a,b)=>a.port.localeCompare(b.port)||a.goods.localeCompare(b.goods));data.pages.markets.left.knowledgeTitle='World knowledge';data.pages.markets.left.knowledge=knowledge;
 const rows=[...market.values()],activeCommodity=rows.some(row=>row.commodityId===selectedCommodity)?selectedCommodity:(rows[0]?.commodityId??null),history=histories.find(item=>item.commodityId===activeCommodity),portHistory=history?.ports?.find(item=>item.id===port.id),historyTime=Number(history?.time??info.time??0),start=Number(rangeSeconds)>0?Math.max(0,historyTime-Number(rangeSeconds)):0;let points=portHistory?.points??[];if(start>0){const prior=points.findLast?.(point=>Number(point.time)<start),recent=points.filter(point=>Number(point.time)>=start);points=prior?[{...prior,time:start},...recent]:recent;}const graphPoints=points.map(point=>({label:clockLabel(point.time),value:Number(point.price??0),time:point.time,eventId:point.eventId??null}));const selectedName=activeCommodity?name(activeCommodity):'No active market';data.pages.markets.right.title=`${selectedName} price history`;data.pages.markets.right.priceHistory={title:`${selectedName} price history`,unit:'gold',points:graphPoints,ranges:[{seconds:0,label:'All'},{seconds:600,label:'10 min'},{seconds:300,label:'5 min'}],selectedRange:Number(rangeSeconds)||0};data.pages.markets.right.source={observedAt:`Tick ${history?.tick??info.tick??'—'}`,confidence:history?1:0};data.pages.markets.right.context=history?`Recorded market prices for ${selectedName}. Use the time controls to narrow the view.`:`No recorded price history for ${selectedName} yet.`;
 return data;
}
